	private void processElement(List<IMendixObject> groupList, List<IMendixObject> groupElementList, Element rootElement) {
		IMendixObject mxGroup = Core.instantiate(getContext(), GroupEntity);
		String groupId = rootElement.getAttribute("id");
		
		for(GroupPropertyMapping groupPropertyMapping : PropertyMappings) {
			if(rootElement.hasAttribute(groupPropertyMapping.getPropertyName())) {
				mxGroup.setValue(getContext(), groupPropertyMapping.getMendixAttributeName(), rootElement.getAttribute(groupPropertyMapping.getPropertyName()));
			}
		}
		mxGroup.setValue(getContext(), Group.MemberNames.GroupId.toString(), groupId);
		mxGroup.setValue(getContext(), Group.MemberNames.GroupIsSelectable.toString(), GroupIsSelectable);
		mxGroup.setValue(getContext(), Group.MemberNames.GroupElementPropsType.toString(), ElementPropsType.toString());
		mxGroup.setValue(getContext(), Group.MemberNames.Group_SvgContainer.toString(), __ParentContainer.getId());
		groupList.add(mxGroup);
		
		NodeList children = rootElement.getChildNodes();
		if(children == null) {
			return;
		}
		
	    int childrenLength = children.getLength();
	    for (int i = 0; i < childrenLength; i++) {
	    	if (children.item(i).getNodeType() == Node.ELEMENT_NODE) {
	    		Element childElement = (Element) children.item(i);
	            String id = childElement.getAttribute("id");
	            String props = null;
	            
	            if(this.ElementPropsType == GroupElementPropsType.Inline) {
	            	List<String> propsList = new ArrayList<String>();
		            if(childElement.hasAttribute("fill")) {
		            	String fill = childElement.getAttribute("fill");
		            	fill = fill.equals("none") ? "transparent" : fill;
		            	propsList.add("\"fill\":\"" + fill + "\"");
		            }
		            
		            if(childElement.hasAttribute("stroke")) {
		            	String stroke = childElement.getAttribute("stroke");
		            	propsList.add("\"stroke\":\"" + stroke + "\"");
		            }
		            
		            if(childElement.hasAttribute("stroke-width")) {
		            	String strokeWidth = childElement.getAttribute("stroke-width");
		            	propsList.add("\"strokeWidth\":" + strokeWidth);
		            }
		            props = String.format("{%s}", String.join(",", propsList));
	            }
	            else {
	            	if(childElement.hasAttribute("props-name")){
	            		props = String.format("\"%s\"",childElement.getAttribute("props-name"));
	            	}
	            }
	            	            
				IMendixObject mxGroupElement = Core.instantiate(getContext(), GroupElement.entityName);
				mxGroupElement.setValue(getContext(), GroupElement.MemberNames.ElementId.toString(), id);
				mxGroupElement.setValue(getContext(), GroupElement.MemberNames.GroupElement_Group.toString(), mxGroup.getId());
				mxGroupElement.setValue(getContext(), GroupElement.MemberNames.Order.toString(), i + 1);
				mxGroupElement.setValue(getContext(), GroupElement.MemberNames.Props.toString(), props);
				groupElementList.add(mxGroupElement);

	            switch(childElement.getNodeName()) {
	            	case "path":
	            		String d = childElement.getAttribute("d");
						addElementProperty(ENUM_ValueType.Decimal, "path", d, mxGroupElement);
	            		break;
	            	case "rect":
	            		String x = childElement.getAttribute("x");
	            		String y = childElement.getAttribute("y");	
	            		String width = childElement.getAttribute("width");
	            		String height = childElement.getAttribute("height");
	            		addElementProperty(ENUM_ValueType.Decimal, "x", x, mxGroupElement);
	            		addElementProperty(ENUM_ValueType.Decimal, "y", y, mxGroupElement);
	            		addElementProperty(ENUM_ValueType.Decimal, "width", width, mxGroupElement);
	            		addElementProperty(ENUM_ValueType.Decimal, "height", height, mxGroupElement);
	            		break;
	            	case "line":
	            		String x1 = childElement.getAttribute("x1");
	            		String y1 = childElement.getAttribute("y1"); 
	            		String x2 = childElement.getAttribute("x2");
	            		String y2 = childElement.getAttribute("y2");
	            		String coordinates = String.format("[%s,%s,%s,%s]", x1, y1, x2, y2);
						addElementProperty(ENUM_ValueType.String, "coords", coordinates, mxGroupElement);
	            		break;
	            	case "g":
	            		_log.debug("Nested group with ID: " + id);
	            		processElement(groupList, groupElementList, childElement);
	            		break;
	            	default:
	            		_log.warn("Element ID: " + id + ", unsupported element type: " + childElement.getNodeName());
	            		break;
	            }	            
	        }
	    }
	}	
	
	private Boolean ObjectIsSpecialisationOf(String ObjectToCheckCompleteName, String SuperObjectCompleteName){
		
		IMetaObject meta = Core.getMetaObject(ObjectToCheckCompleteName);
		
		Boolean matchFound = false;
		IMetaObject superObjects[] = new IMetaObject[meta.getSuperObjects().size()];
		superObjects = meta.getSuperObjects().toArray(superObjects);
		for(IMetaObject superObject : superObjects){
			String superName = superObject.getName();
			if( SuperObjectCompleteName.equals(superName) ){
				matchFound = true;
				break;
			}
		}
		
		return matchFound;
	}

	private IMendixObject addElementProperty(ENUM_ValueType valueType, String key, Object value, IMendixObject group) {
		IMendixObject mxProperty = Core.instantiate(getContext(), ElementProperty.entityName);
		mxProperty.setValue(getContext(), ElementProperty.MemberNames.Key.toString(), key);
	    mxProperty.setValue(getContext(), ElementProperty.MemberNames.ValueType.toString(), valueType);
	    mxProperty.setValue(getContext(), ElementProperty.MemberNames.ElementProperty_GroupElement.toString(), group);

		switch (valueType) {
			case Date:
				mxProperty.setValue(getContext(), ElementProperty.MemberNames.DateValue.toString(), value);
				break;
			case Decimal:
				mxProperty.setValue(getContext(), ElementProperty.MemberNames.DecimalValue.toString(), value);
				break;
			case Integer:
				mxProperty.setValue(getContext(), ElementProperty.MemberNames.IntegerValue.toString(), value);
				break;
			case String:
				mxProperty.setValue(getContext(), ElementProperty.MemberNames.StringValue.toString(), value);
				break;
			case _Boolean:
				mxProperty.setValue(getContext(), ElementProperty.MemberNames.BooleanValue.toString(), value);
				break;
			case _Long:
				mxProperty.setValue(getContext(), ElementProperty.MemberNames.LongValue.toString(), value);
				break;
		}

		return mxProperty;
	}
	
